custom:
float2 worldScale = float2(length(BasisX), length(BasisY));
float2 footprint = max(min(UnitSize, 5.0 * worldScale), 0.0001);
float2 uv = Local.xy * worldScale / footprint + Offset;
float4 mask = Texture2DSample(Tex, TexSampler, saturate(uv));
int channel = (int)clamp(floor(Random), 0, 3);
float density = channel == 0 ? mask.r : (channel == 1 ? mask.g : (channel == 2 ? mask.b : max(mask.r, max(mask.g, mask.b))));
float2 p = abs(Local.xy)/2.5;
float radius = saturate(KZBloodProjectionCornerFraction);
float2 q = p-(1.0-radius);
float sd = length(max(q,0.0))+min(max(q.x,q.y),0.0)-radius;
float width = max(fwidth(sd),KZBloodProjectionEdgeFeather);
float volume = 1.0-smoothstep(-width,0.0,sd);
float zdist = abs(Local.z);
volume *= 1.0-smoothstep(2.5-max(fwidth(zdist),0.0001),2.5,zdist);
float uvValid = step(0, uv.x) * step(uv.x, 1) * step(0, uv.y) * step(uv.y, 1);
bool cameraInside = all(abs(CameraLocal) <= 2.5);
float faceValid = cameraInside ? step(Face, 0) : step(0, Face);
float opacity = saturate(density * PC.a) * volume * uvValid * faceValid;
return float4(PC.rgb, opacity);
